(function () {
  'use strict';

  var api = 'https://api.leancloud.cn/1.1/classes/Counter';
  var appId = 'pGdwyT4C1SLK3tNu5BiWT5wK-gzGzoHsz';
  var appKey = 't07S7p0VCiw6wR6HdlEjli0G';
  var headers = {
    'Content-Type': 'application/json',
    'X-LC-Id': appId,
    'X-LC-Key': appKey
  };
  var siteNode = document.getElementById('busuanzi_value_site_pv') ||
    document.getElementById('busuanzi_value_site_uv');
  var pageNode = document.getElementById('busuanzi_value_page_pv');

  function show(node, value) {
    if (node) node.textContent = value;
  }

  function json(response) {
    if (!response.ok) throw new Error('counter request failed');
    return response.json();
  }

  function find(key) {
    var where = encodeURIComponent(JSON.stringify({ url: key }));
    return fetch(api + '?where=' + where + '&limit=1', {
      headers: headers,
      cache: 'no-store',
      mode: 'cors'
    }).then(json).then(function (data) {
      return data.results && data.results[0];
    });
  }

  function increment(record) {
    return fetch(api + '/' + record.objectId, {
      method: 'PUT',
      headers: headers,
      body: JSON.stringify({
        time: { __op: 'Increment', amount: 1 }
      }),
      cache: 'no-store',
      mode: 'cors'
    }).then(json).then(function () {
      return (record.time || 0) + 1;
    });
  }

  function create(key, title) {
    return fetch(api, {
      method: 'POST',
      headers: headers,
      body: JSON.stringify({ title: title, url: key, time: 1 }),
      cache: 'no-store',
      mode: 'cors'
    }).then(json).then(function () {
      return 1;
    });
  }

  function hit(key, title, node) {
    if (!node) return;
    if (!window.fetch) {
      show(node, '—');
      return;
    }
    show(node, '…');
    find(key).then(function (record) {
      return record ? increment(record) : create(key, title);
    }).then(function (value) {
      show(node, String(value));
    }).catch(function () {
      show(node, '—');
    });
  }

  show(siteNode, '…');
  show(pageNode, '…');

  hit('__site__', 'Shadow.Net site total', siteNode);
  hit(window.location.pathname, document.title, pageNode);
})();
